573:          * Initializes the test instance and sets the context's elapsed time based on the passed
574:          * callback.
575:          */
576:         private DefaultRescaleManager createTestInstance(Runnable timeTransitioning) {
577:             final DefaultRescaleManager testInstance =
578:                     new DefaultRescaleManager(
579:                             initializationTime,
580:                             // clock that returns the time based on the configured elapsedTime
581:                             () -> Objects.requireNonNull(initializationTime).plus(elapsedTime),
582:                             this,
583:                             SCALING_MIN,
584:                             SCALING_MAX,
585:                             Duration.ofHours(5)) {
586:                         @Override
587:                         public void onChange() {
588:                             super.onChange();
589: 
590:                             // hack to avoid calling this method in every test method
591:                             // we want to trigger tasks that are meant to run right-away
592:                             TestingRescaleManagerContext.this.triggerOutdatedTasks();
593:                         }
594: 
595:                         @Override
596:                         public void onTrigger() {
597:                             super.onTrigger();
598: 
599:                             // hack to avoid calling this method in every test method
600:                             // we want to trigger tasks that are meant to run right-away
601:                             TestingRescaleManagerContext.this.triggerOutdatedTasks();
602:                         }
603:                     };
604: 
605:             timeTransitioning.run();
606:             return testInstance;
607:         }
608: 
609:         // ///////////////////////////////////////////////
610:         // Time-adjustment functionality
611:         // ///////////////////////////////////////////////
612: 
613:         /**
614:          * Transitions the context's time to a moment that falls into the test instance's cooldown
615:          * phase.
616:          */
617:         public void transitionIntoCooldownTimeframe() {
618:             this.elapsedTime = SCALING_MIN.dividedBy(2);
619:             this.triggerOutdatedTasks();
620:         }
621: 
622:         /**
623:          * Transitions the context's time to a moment that falls into the test instance's
624:          * soft-scaling phase.
625:          */
626:         public void transitionIntoSoftScalingTimeframe() {
627:             // the state transition is scheduled based on the current event's time rather than the
628:             // initializationTime
629:             this.elapsedTime = elapsedTime.plus(SCALING_MIN);
630: 
631:             // make sure that we're still below the scalingIntervalMax
632:             this.elapsedTime = elapsedTime.plus(SCALING_MAX.minus(elapsedTime).dividedBy(2));
633:             this.triggerOutdatedTasks();
634:         }
635: 
636:         /**
637:          * Transitions the context's time to a moment that falls into the test instance's
638:          * hard-scaling phase.
639:          */
640:         public void transitionIntoHardScalingTimeframe() {
641:             // the state transition is scheduled based on the current event's time rather than the
642:             // initializationTime
643:             this.elapsedTime = elapsedTime.plus(SCALING_MAX).plusMinutes(1);
644:             this.triggerOutdatedTasks();
645:         }
646: 
647:         private void triggerOutdatedTasks() {
648:             while (!scheduledTasks.isEmpty()) {
649:                 final Instant timeOfExecution = scheduledTasks.firstKey();
650:                 if (!timeOfExecution.isAfter(
651:                         Objects.requireNonNull(initializationTime).plus(elapsedTime))) {
652:                     scheduledTasks.remove(timeOfExecution).forEach(Runnable::run);
653:                 } else {
654:                     break;
655:                 }
656:             }
657:         }
