661:         // ///////////////////////////////////////////////
662: 
663:         public boolean rescaleWasTriggered() {
664:             return rescaleTriggered.get();
665:         }
666: 
667:         public int numberOfTasksWaiting() {
668:             return scheduledTasks.size();
669:         }
670: 
671:         public boolean additionalTasksWaiting() {
672:             return !scheduledTasks.isEmpty();
673:         }
